package com.company.platform.analytics.infrastructure;
import java.util.UUID;import org.springframework.security.core.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Component;
@Component public class SecurityTenantContextProvider implements TenantContextProvider{public UUID currentTenantId(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(!(a instanceof JwtAuthenticationToken j)||!a.isAuthenticated())throw new IllegalStateException("authenticated tenant context required");Object v=j.getToken().getClaims().getOrDefault("tenant_id",j.getToken().getClaims().get("tenantId"));if(v==null)throw new IllegalStateException("tenant_id claim required");return UUID.fromString(v.toString());}}
